int main(){try{Document d(6,4);const auto firstFrame=d.frame().id;name(d,U"dup.png");const auto bottom=d.layer().id;d.beginStroke({1,1},0xff0000ff);d.commitStroke();d.addFrame();d.beginStroke({2,1},0xff00ff00);d.commitStroke();d.selectFrame(firstFrame);d.addLayer();name(d,U"DUP.JPG");const auto middle=d.layer().id;d.beginStroke({4,2},0x80ff0000);d.commitStroke();d.setLayerOpacity(.5);d.addLayer();name(d,U".png");const auto top=d.layer().id;d.setLayerVisible(false);d.markSaved();const auto history=d.historySize(),revision=d.revision();const auto owned=std::filesystem::path("animation-layers-core-owned")/std::to_string(std::chrono::steady_clock::now().time_since_epoch().count());std::filesystem::create_directories(owned);const auto ids=std::vector<std::string>{bottom,middle,top};check(animationExportLayerIds(d.timeline().state())==ids&&animationExportLayerIds(d.timeline().state(),"deleted")==ids&&animationExportLayerIds(d.timeline().state(),middle)==std::vector<std::string>{middle},"Legacy order/invalid fallback/valid layer");auto plan=*planAnimationLayerExport(d,"deleted",owned,U"base.name.webp",true,{});check(plan.layerIds==ids&&plan.paths[0].filename()==L"base.name-dup.webp"&&plan.paths[1].filename()==L"base.name-DUP-2.webp"&&plan.paths[2].filename()==L"base.name-layer-3.webp","Actual legacy service name oracle");DocumentSnapshot snapshot(d);while(!snapshot.advance(d,std::chrono::steady_clock::now()+std::chrono::seconds(1))){}auto copy=snapshot.finish();AnimationLayerExportOptions options;options.animation.scalePercent=150;options.animation.frameStart=2;options.animation.frameEnd=2;options.animation.trimCommon=true;options.animation.protection=ExportProtection::Blur;options.webp=true;check(writeAnimationLayerExport(copy,options,plan)==3,"Batch snapshot writes");for(std::size_t i=0;i<ids.size();++i){auto single=options.animation;single.layerId=ids[i];check(read(plan.paths[i])==encodeAnimationWebp(d,single).bytes,"Actual isolated layer output");}int conflicts=0;auto canceled=planAnimationLayerExport(d,{},owned,U"base.name.webp",true,[&](const auto&,const auto&){++conflicts;return ExportConflictChoice::Cancel;});check(!canceled&&conflicts==1,"Preflight cancellation");conflicts=0;auto renamed=*planAnimationLayerExport(d,{},owned,U"base.name.webp",true,[&](const auto&,const auto&){++conflicts;return ExportConflictChoice::RenameAll;});check(conflicts==1&&renamed.paths[0].filename()==L"base.name-dup (1).webp"&&renamed.paths[2].filename()==L"base.name-layer-3 (1).webp","Shared rename-all conflict plan");bool stop=false;check(writeAnimationLayerExport(d,options,renamed,[&]{return stop;},[&](auto n,auto){stop=n==1;})==1&&std::filesystem::exists(renamed.paths[0])&&!std::filesystem::exists(renamed.paths[1]),"Real partial cancellation");auto fail=*planAnimationLayerExport(d,{},owned,U"failure.gif",false,{});fail.paths[1]=owned/"missing"/"second.gif";options.webp=false;bool failed=false;try{writeAnimationLayerExport(d,options,fail);}catch(const std::exception&){failed=true;}check(failed&&std::filesystem::exists(fail.paths[0])&&!std::filesystem::exists(fail.paths[2]),"Real partial failure preserves first and skips last");auto single=options.animation;single.layerId=bottom;check(read(fail.paths[0])==encodeAnimationGif(d,single).bytes,"GIF batch reused codec");check(d.historySize()==history&&d.revision()==revision&&!d.dirty()&&d.layer().id==top&&d.frame().id==firstFrame,"Batch source history and active IDs");std::cout<<"Animation layer batch legacy planning, snapshot, both codecs, preflight, partial cancel/failure passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
